function crownDepthHash(v){return typeof missionHash==='function'?Math.abs(missionHash(String(v))):String(v).split('').reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261)}
function createCrownDepthState(seed){let society={};for(const [id,g] of Object.entries(CROWN_SOCIETY_GROUPS))society[id]={id,power:22+crownDepthHash(seed+id)%37,satisfaction:38+crownDepthHash(id+seed)%29,radicalism:8+crownDepthHash('r'+id+seed)%27,wealth:30+crownDepthHash('w'+id+seed)%40,momentum:0,history:[]};let rivals={};for(const n of ['Ravengar','Nordhaven','Eldoria','Aurelia','Lysara'])rivals[n]={country:n,respect:24+crownDepthHash(seed+n)%46,resentment:8+crownDepthHash(n+seed)%34,bond:0,status:'rival',encounters:[],lastTurn:0};return {version:1,household:{roles:Object.fromEntries(Object.keys(CROWN_HOUSEHOLD_ROLES).map(id=>[id,{personId:null,since:null,trust:50,history:[]}])),selected:'physician'},festival:{draft:{type:'tournament',scale:'court',guests:'all',focus:'honor'},active:null,history:[]},rivals,selectedRival:'Ravengar',secrets:[],selectedSecret:null,palace:{rooms:Object.fromEntries(Object.entries(CROWN_PALACE_ROOMS).map(([id,r])=>[id,{level:r.base,construction:null,usedTurn:0,history:[]}])),selected:'throne',prestige:8},society,lawDraft:{subject:'all',right:'protection',funding:'treasury',oversight:'courts',enforcement:'mediation',exception:'none'},customLaws:[],lastLawYear:1483,expedition:{draft:{captain:null,fleet:1,purpose:'science',route:'north',conduct:'open'},active:null,history:[],discoveries:[]},memories:[],traitScores:Object.fromEntries(Object.keys(CROWN_MEMORY_TRAITS).map(k=>[k,0])),traits:[],legacies:[],news:[]}}
function migrateCrownDepth(old,seed){let f=createCrownDepthState(seed),c=old&&typeof old==='object'?old:{};c={...f,...c,household:{...f.household,...(c.household||{})},festival:{...f.festival,...(c.festival||{})},rivals:{...f.rivals,...(c.rivals||{})},palace:{...f.palace,...(c.palace||{})},expedition:{...f.expedition,...(c.expedition||{})},lawDraft:{...f.lawDraft,...(c.lawDraft||{})},traitScores:{...f.traitScores,...(c.traitScores||{})}};for(const id in f.household.roles)c.household.roles[id]={...f.household.roles[id],...(c.household.roles?.[id]||{}),history:Array.isArray(c.household.roles?.[id]?.history)?c.household.roles[id].history:[]};for(const id in f.palace.rooms)c.palace.rooms[id]={...f.palace.rooms[id],...(c.palace.rooms?.[id]||{}),history:Array.isArray(c.palace.rooms?.[id]?.history)?c.palace.rooms[id].history:[]};c.society={...f.society,...(c.society||{})};for(const id in f.society)c.society[id]={...f.society[id],...(c.society[id]||{}),history:Array.isArray(c.society[id]?.history)?c.society[id].history:[]};for(const n in f.rivals)c.rivals[n]={...f.rivals[n],...(c.rivals[n]||{}),encounters:Array.isArray(c.rivals[n]?.encounters)?c.rivals[n].encounters:[]};for(const key of ['secrets','customLaws','memories','traits','legacies','news'])c[key]=Array.isArray(c[key])?c[key]:f[key];c.festival.history=Array.isArray(c.festival.history)?c.festival.history:[];c.expedition.history=Array.isArray(c.expedition.history)?c.expedition.history:[];c.expedition.discoveries=Array.isArray(c.expedition.discoveries)?c.expedition.discoveries:[];return c}
function ensureCrownDepth(){if(!state.crownDepth)state.crownDepth=migrateCrownDepth(null,state.nameSeed);return state.crownDepth}
function crownDepthNews(title,text,kind='crown'){let c=ensureCrownDepth();c.news.unshift({turn:state.turn,year:state.year,title,text,kind});c.news=c.news.slice(0,60)}
function crownDepthPerson(id){return typeof livingPerson==='function'?livingPerson(id):null}
function crownDepthQual(v){return v<25?'gering':v<50?'spürbar':v<75?'stark':'beherrschend'}
function crownDepthCommit(title,text,kind='realm'){recordDecision(title,text,{kind});crownDepthNews(title,text,kind);normalizeState();persist();render()}

function crownHouseholdPanel(){let c=ensureCrownDepth(),selected=CROWN_HOUSEHOLD_ROLES[c.household.selected],slot=c.household.roles[c.household.selected],person=crownDepthPerson(slot.personId),assigned=new Set(Object.values(c.household.roles).map(x=>x.personId).filter(Boolean)),people=ensureLiving().people.filter(p=>p.alive&&['court','council','faith','family','private'].includes(p.group)).slice(0,18),roles=Object.entries(CROWN_HOUSEHOLD_ROLES).map(([id,r])=>{let s=c.household.roles[id],p=crownDepthPerson(s.personId);return `<button data-crown-household="select:${id}" class="household-role ${id===c.household.selected?'active':''}"><i>${r.icon}</i><span><small>${p?'BESETZT SEIT '+s.since:'UNBESETZT'}</small><b>${r.name}</b><em>${p?.name||'Niemand führt dieses Amt'}</em></span></button>`}).join(''),candidates=people.map(p=>{let fit=selected.apt.filter(t=>p.traits.includes(t)).length;return `<button data-crown-household="appoint:${c.household.selected}:${p.id}" ${assigned.has(p.id)&&p.id!==slot.personId?'disabled':''}><b>${p.name}</b><span>${p.role} · ${fit===2?'hervorragend':fit===1?'geeignet':'ungeprüft'} · Beziehung ${Math.round(p.relation)}</span></button>`}).join('');return panel('DER KÖNIGLICHE HAUSHALT','Acht persönliche Ämter mit Menschen, Erinnerungen und eigener Macht',`<div class="household-layout"><div class="household-roles">${roles}</div><div class="household-office"><small>${selected.icon} PERSÖNLICHES KRONAMT</small><h2>${selected.name}</h2><p>${selected.text}</p>${person?`<div class="office-holder"><b>${person.name}</b><span>${person.role} · Vertrauen ${slot.trust} · Einfluss ${person.influence}</span><blockquote>${slot.history[0]?.text||'Noch wurde dieses Amt nicht durch eine gemeinsame Krise geprüft.'}</blockquote><div><button data-crown-household="consult:${c.household.selected}">DAS AMT PERSÖNLICH NUTZEN</button><button class="danger" data-crown-household="dismiss:${c.household.selected}">AUS DEM AMT ENTLASSEN</button></div></div>`:`<div class="office-candidates"><h3>WEN IHR BERUFEN KÖNNT</h3>${candidates}</div>`}</div></div>`,'span-12')}
function crownHouseholdAction(code){let [act,roleId,personId]=code.split(':'),c=ensureCrownDepth(),def=CROWN_HOUSEHOLD_ROLES[roleId],slot=c.household.roles[roleId];if(act==='select'&&def){c.household.selected=roleId;persist();render(false);return true}if(!def||!slot)return false;if(act==='appoint'){let p=crownDepthPerson(personId);if(!p||Object.values(c.household.roles).some(x=>x.personId===personId&&x!==slot))return false;slot.personId=personId;slot.since=state.year;slot.trust=clamp(Math.round((p.relation+p.trust)/2),20,90);slot.history.unshift({year:state.year,text:`${p.name} wurde persönlich in das Amt berufen.`});livingAddMemory(p.id,'In den königlichen Haushalt berufen',`Der König übertrug ${p.name} das Amt ${def.name}.`,4,4);crownDepthCommit(`Haushalt · ${def.name}`,`${p.name} erhält Zugang, Verantwortung und den Rang dieses persönlichen Amtes.`,'private');return true}if(act==='dismiss'){let p=crownDepthPerson(slot.personId);if(!p)return false;livingAddMemory(p.id,'Aus dem Haushalt entlassen',`Das Amt ${def.name} wurde ${p.name} entzogen.`,-6,5);slot.history.unshift({year:state.year,text:`${p.name} wurde entlassen; Beziehungen und Wissen bleiben.`});slot.personId=null;slot.trust=40;crownDepthCommit(`Haushalt · Entlassung`,`${p.name} verliert das Amt ${def.name}, aber nicht die Erinnerungen an den innersten Hof.`,'private');return true}if(act==='consult'){let p=crownDepthPerson(slot.personId);if(!p||slot.usedTurn===state.turn)return false;slot.usedTurn=state.turn;slot.trust+=3;if(roleId==='physician'){state.private.health+=7;state.private.stress-=2}else if(roleId==='confessor'){state.private.stress-=7;ensurePrivateWorld().conscience+=5}else if(roleId==='guard'){state.life.courage+=2;state.stats.legitimacy+=1}else if(roleId==='tutor'){state.life.education+=2;for(const ch of state.life.children)ch.education=(ch.education||0)+1}else if(roleId==='poet'){state.private.reputation+=4;c.palace.prestige+=2}else if(roleId==='chamberlain'){state.life.authority+=2;c.festival.draft.scale='grand'}else if(roleId==='favorite'){state.private.stress-=8;state.factions.nobles-=1}else{state.private.purse+=160000;state.reserve-=80000}let text=`${p.name} nutzt Zugang und Erfahrung als ${def.name}; die Zusammenarbeit wird als gemeinsame Erinnerung festgehalten.`;slot.history.unshift({year:state.year,text});livingAddMemory(p.id,'Das persönliche Amt bewährt sich',text,4,3);crownDepthCommit(`Haushalt · ${def.name}`,text,'private');return true}return false}

function crownFestivalPanel(){let c=ensureCrownDepth(),f=c.festival;if(f.active){let e=CROWN_FESTIVAL_EVENTS.find(x=>x.id===f.active.events[f.active.index]);return panel('DAS HOFFEST LEBT',e.title,`<div class="festival-live"><img src="assets/crown-festival-depth.webp" alt="Fest im Hof von Falkenkrone"><div><small>${CROWN_FESTIVALS[f.active.type].name} · SZENE ${f.active.index+1} VON ${f.active.events.length}</small><h2>${e.title}</h2><p>${e.text}</p><div class="festival-event-choices">${e.choices.map(x=>`<button data-crown-festival="resolve:${x[0]}"><b>${x[1]}</b><span>Diese Antwort prägt Gäste, Erinnerungen und den Ruf des Festes.</span></button>`).join('')}</div></div></div>`,'span-12')}let d=f.draft,types=Object.entries(CROWN_FESTIVALS).map(([id,x])=>`<button data-crown-festival="type:${id}" class="${d.type===id?'active':''}"><i>${x.icon}</i><b>${x.name}</b><span>${x.text}</span></button>`).join(''),controls=[['scale','court','AUSGEWÄHLTER HOF'],['scale','grand','DAS GANZE REICH'],['guests','all','ALLE STÄNDE'],['guests','foreign','FREMDE HÖFE'],['focus','honor','EHRE UND RANG'],['focus','freedom','FREIHEIT UND NÄHE']].map(x=>`<button data-crown-festival="${x[0]}:${x[1]}" class="${d[x[0]]===x[1]?'active':''}">${x[2]}</button>`).join(''),cost=d.scale==='grand'?2800000:900000;return panel('FESTE, TURNIERE UND NÄCHTE DES HOFES','Jedes Fest wird geplant und danach in drei eigenständigen Szenen gespielt',`<div class="festival-hero"><img src="assets/crown-festival-depth.webp" alt="Valdorisches Kronfest"><div><h2>DER HOF ALS BÜHNE</h2><p>Turnier, Masken, Kunst und Volksnähe bringen Haushalt, Rivalen, Familie und Gesellschaft an denselben Ort.</p></div></div><div class="festival-types">${types}</div><div class="festival-controls">${controls}<button class="festival-start" data-crown-festival="start" ${state.reserve<cost?'disabled':''}>FEST FÜR ${fmt(cost)} ₲ ERÖFFNEN</button></div>`,'span-12')}
function crownFestivalAction(code){let [act,val]=code.split(':'),c=ensureCrownDepth(),f=c.festival;if(act==='type'&&CROWN_FESTIVALS[val]){f.draft.type=val;persist();render(false);return true}if(['scale','guests','focus'].includes(act)){f.draft[act]=val;persist();render(false);return true}if(act==='start'){if(f.active)return false;let cost=f.draft.scale==='grand'?2800000:900000;if(state.reserve<cost)return false;state.reserve-=cost;let ids=CROWN_FESTIVAL_EVENTS.map(x=>x.id),offset=crownDepthHash(`${state.nameSeed}:${state.turn}:${f.draft.type}`)%ids.length;f.active={...f.draft,started:state.year,index:0,events:[ids[offset],ids[(offset+3)%ids.length],ids[(offset+6)%ids.length]],choices:[]};crownDepthCommit(`Hoffest · ${CROWN_FESTIVALS[f.draft.type].name}`,`Das Fest wird als ${f.draft.scale==='grand'?'Reichsfest':'ausgewähltes Hoffest'} eröffnet. Drei Situationen werden seinen wahren Charakter bestimmen.`,'private');return true}if(act==='resolve'&&f.active){let e=CROWN_FESTIVAL_EVENTS.find(x=>x.id===f.active.events[f.active.index]),choice=e?.choices.find(x=>x[0]===val);if(!choice)return false;f.active.choices.push({event:e.id,choice:val});let humane=['reconcile','spouse','lead','help','open','applaud'].includes(val),bold=['enter','demand','crown','signal'].includes(val);if(humane){state.life.empathy+=2;state.factions.people+=2;ensureCrownDepth().traitScores.guardian+=2}if(bold){state.life.courage+=2;state.private.reputation+=2}if(['accept','private','permit'].includes(val)){ensurePrivateWorld().exposure+=3;ensurePrivateWorld().freedom+=2}if(['guard','household'].includes(val)){let guard=c.household.roles.guard;if(guard.personId){guard.trust+=4;livingAddMemory(guard.personId,'Beim Hoffest bewährt',e.text,4,3)}else state.private.reputation-=2}f.active.index++;if(f.active.index>=f.active.events.length){let done={...f.active,ended:state.year};f.history.unshift(done);f.history=f.history.slice(0,20);f.active=null;c.palace.prestige+=5;state.stats.legitimacy+=3;crownDepthCommit(`Das Fest endet · ${CROWN_FESTIVALS[done.type].name}`,`Drei Entscheidungen haben das Fest geprägt. Gäste tragen ihre eigene Fassung in Familien, Straßen und fremde Höfe.`,'private')}else crownDepthCommit(`Hoffest · ${e.title}`,`${choice[1]}. Die nächste Szene entsteht aus der Atmosphäre, die diese Entscheidung hinterlässt.`,'private');return true}return false}

function crownRivalStatus(r,war){return r.status==='captured'?'GEFANGEN NACH DEM FALL DER HAUPTSTADT':r.status==='prisoner'?'UNTER KÖNIGLICHEM HAUSARREST':r.status==='released'?'FREIGELASSENE BESIEGTE KRONE':r.status==='guest'?'IM VALDORISCHEN EXIL':war?'IM KRIEG MIT VALDORIA':'HERRSCHENDE KRONE'}
function crownRivalsPanel(){let c=ensureCrownDepth(),n=c.selectedRival,r=c.rivals[n],f=livingForeignRealm(n),war=state.diplo[n]?.war,world=state.depth?.world?.[n],captive=r.status==='captured'||r.status==='prisoner',cards=Object.keys(c.rivals).map(name=>{let x=c.rivals[name],ff=livingForeignRealm(name),label={rival:'FREMDE KRONE',guest:'EXIL',captured:'GEFANGEN',prisoner:'HAUSARREST',released:'FREIGELASSEN'}[x.status]||x.status;return `<button data-crown-rival="select:${name}" class="rival-card ${name===n?'active':''}"><small>${label}</small><b>${ff.ruler}</b><span>${name} · Respekt ${x.respect} · Groll ${x.resentment}</span></button>`}).join(''),history=r.encounters.slice(0,4).map(x=>`<article><time>${x.year}</time><b>${x.title}</b><span>${x.text}</span></article>`).join('')||'<div class="empty">Noch verbindet beide Herrscher keine persönliche Begegnung.</div>',normalActions=`<button data-crown-rival="write:${n}"><b>PERSÖNLICH SCHREIBEN</b><span>Nicht Gesandte, sondern zwei Herrscher sprechen.</span></button><button data-crown-rival="invite:${n}" ${war||state.reserve<500000?'disabled':''}><b>NACH FALKENKRONE EINLADEN</b><span>Begegnung, Haushalt und Hof tragen das Risiko.</span></button><button data-crown-rival="challenge:${n}" ${state.life.age<18?'disabled':''}><b>ÖFFENTLICH HERAUSFORDERN</b><span>Turnier, Debatte oder Flottenmanöver entscheiden Rang.</span></button><button data-crown-rival="mercy:${n}" ${!war&&r.resentment<55?'disabled':''}><b>PERSÖNLICHE GNADE ANBIETEN</b><span>Eine Feindschaft soll enden, ohne vergessen zu werden.</span></button><button data-crown-rival="exile:${n}" ${war||r.respect<55||world?.power>42?'disabled':''}><b>ZUFLUCHT IN VALDORIA BIETEN</b><span>Eine schwache fremde Krone wird zum gefährlichen Gast.</span></button>`,captiveActions=`<button data-crown-rival="release:${n}"><b>OHNE PREIS FREILASSEN</b><span>Persönliche Gnade stärkt den Frieden, enttäuscht aber Kriegsgewinner.</span></button><button data-crown-rival="arrest:${n}"><b>EHRENVOLLEN HAUSARREST VERHÄNGEN</b><span>Die besiegte Krone bleibt im Palast: sicher, sichtbar und gefährlich.</span></button><button data-crown-rival="ransom:${n}"><b>LÖSEGELD UND THRONVERZICHT</b><span>2,5 Mio. Gold für die Staatsreserve; die Demütigung bleibt politisch wirksam.</span></button>`;return panel('KRONEN MIT GESICHTERN','Fremde Herrscher erinnern Respekt, Demütigung, Gnade und gemeinsame Erlebnisse',`<div class="rival-roster">${cards}</div><div class="rival-stage"><div><small>${n} · GENERATION ${f.generation}</small><h2>${f.ruler}</h2><p>${f.temper} · ${f.age} Jahre · ${crownRivalStatus(r,war)}</p><div class="rival-measures"><span>RESPEKT<i><b style="width:${r.respect}%"></b></i></span><span>GROLL<i><b style="width:${r.resentment}%"></b></i></span><span>PERSÖNLICHE BINDUNG<i><b style="width:${r.bond}%"></b></i></span></div></div><div class="rival-actions">${captive?captiveActions:normalActions}</div><div class="rival-history">${history}</div></div>`,'span-12')}
function crownRivalAction(code){let [act,n]=code.split(':'),c=ensureCrownDepth(),r=c.rivals[n],f=livingForeignRealm(n);if(act==='select'&&r){c.selectedRival=n;persist();render(false);return true}if(!r||r.lastTurn===state.turn)return false;let title='',text='';if(act==='write'){r.respect+=3;r.bond+=4;state.relations[n]+=2;title='Ein Brief zwischen zwei Kronen';text=`${f.ruler} erhält Worte in der Handschrift des Königs statt eine ausgehandelte Depesche.`}else if(act==='invite'){if(state.diplo[n]?.war||state.reserve<500000)return false;state.reserve-=500000;r.respect+=7;r.bond+=9;r.resentment-=3;title=`${f.ruler} in Falkenkrone`;text='Beide Herrscher teilen Tafel, Palast und mehrere Gespräche ohne ihre vollständigen Höfe.'}else if(act==='challenge'){if(state.life.age<18)return false;let win=crownDepthHash(`${state.nameSeed}:${state.turn}:${n}:challenge`)%100<clamp(48+state.life.courage/4-f.age/8,25,80);r.respect+=win?9:5;r.resentment+=win?7:-2;state.private.reputation+=win?4:1;title=win?'Die Herausforderung gewonnen':'Eine ehrenhafte Niederlage';text=`${f.ruler} begegnet dem König in einem öffentlichen Wettstreit. ${win?'Valdoria gewinnt den Tag, aber der fremde Hof erinnert die Demütigung.':'Die Niederlage wird ohne Ausrede angenommen und schafft widerwilligen Respekt.'}`}else if(act==='mercy'){if(!state.diplo[n]?.war&&r.resentment<55)return false;r.resentment-=18;r.respect+=8;r.bond+=5;state.relations[n]+=7;title=`Gnade für ${f.ruler}`;text='Die Krone bietet einen persönlichen Ausweg aus der Feindschaft, ohne vergangenes Unrecht umzuschreiben.'}else if(act==='exile'){let world=state.depth?.world?.[n];if(state.diplo[n]?.war||r.respect<55||world?.power>42)return false;r.status='guest';r.bond+=12;state.factions.nobles-=3;title=`Eine fremde Krone im Exil`;text=`${f.ruler} erhält Schutz und einen Haushalt in Valdoria. Der Gast bringt Ansprüche, Gefolge und Erinnerung mit.`}else if(act==='release'){if(!['captured','prisoner'].includes(r.status))return false;r.status='released';r.defeatResolved=true;r.resentment-=16;r.respect+=14;r.bond+=8;state.relations[n]+=10;state.factions.officers-=3;state.factions.people+=2;title=`${f.ruler} geht ohne Ketten`;text='Der besiegte Herrscher darf mit Gefolge und persönlichem Besitz abreisen. Soldaten verlangen Härte, doch die Welt erinnert königliche Gnade.'}else if(act==='arrest'){if(r.status!=='captured')return false;r.status='prisoner';r.defeatResolved=true;r.resentment+=11;r.respect+=3;state.factions.nobles+=2;state.private.stress+=2;title=`${f.ruler} unter dem Dach des Siegers`;text='Ein ehrenvoller Hausarrest bewahrt Rang und Leben, macht Falkenkrone aber zum dauerhaften Schauplatz der besiegten Dynastie.'}else if(act==='ransom'){if(!['captured','prisoner'].includes(r.status))return false;r.status='released';r.defeatResolved=true;r.resentment+=18;r.respect-=5;state.reserve+=2500000;state.relations[n]-=8;state.stats.legitimacy+=2;title='Gold gegen Krone und Freiheit';text=`${f.ruler} unterzeichnet den Thronverzicht und verlässt Valdoria nach Zahlung von 2,5 Mio. Gold. Der Vertrag beendet die Gefangenschaft, nicht die Demütigung.`}else return false;r.lastTurn=state.turn;r.respect=clamp(r.respect,0,100);r.resentment=clamp(r.resentment,0,100);r.bond=clamp(r.bond,0,100);r.encounters.unshift({year:state.year,title,text});r.encounters=r.encounters.slice(0,16);crownDepthCommit(`Persönliche Rivalität · ${title}`,text,'diplomacy');return true}

function crownSecretsPanel(){let c=ensureCrownDepth(),items=c.secrets.slice(0,12),selected=items.find(x=>x.id===c.selectedSecret)||items[0],list=items.map(s=>`<button data-crown-secret="select:${s.id}" class="secret-file ${selected?.id===s.id?'active':''} ${s.used?'used':''}"><i>${s.category==='private'?'♥':s.category==='foreign'?'♜':'✎'}</i><span><small>${s.category.toUpperCase()} · ${s.year}</small><b>${s.title}</b><em>${s.used?'ABGESCHLOSSEN':'GEWICHT '+s.leverage}</em></span></button>`).join('')||'<div class="empty">Noch besitzt die Schwarze Chronik keinen abgeschlossenen Eintrag. Geheimnisse entstehen aus wirklichen Entscheidungen und Ereignissen.</div>';return panel('DIE SCHWARZE CHRONIK','Bekannte Geheimnisse können bewahrt, vergeben, veröffentlicht oder vernichtet werden',`<div class="secret-archive"><div>${list}</div>${selected?`<article><small>${selected.origin}</small><h2>${selected.title}</h2><p>${selected.text}</p><div class="secret-actions"><button data-crown-secret="keep:${selected.id}">WEITER VERSIEGELN</button><button data-crown-secret="reveal:${selected.id}" ${selected.used?'disabled':''}>VERÖFFENTLICHEN</button><button data-crown-secret="pardon:${selected.id}" ${selected.used?'disabled':''}>PRIVAT VERGEBEN</button><button data-crown-secret="destroy:${selected.id}" ${selected.used?'disabled':''}>BEWEISE VERNICHTEN</button></div></article>`:'<article class="empty">Keine Akte ausgewählt.</article>'}</div>`,'span-12')}
function crownSecretAction(code){let [act,id]=code.split(':'),c=ensureCrownDepth(),s=c.secrets.find(x=>x.id===id);if(act==='select'&&s){c.selectedSecret=id;persist();render(false);return true}if(!s||s.used||s.lastHandledTurn===state.turn)return false;let text='';if(act==='keep'){s.leverage=Math.min(100,s.leverage+2);s.exposure=Math.min(100,(s.exposure||0)+1);text='Die Akte bleibt versiegelt. Ihr Gewicht wächst ebenso wie das Risiko, dass andere von ihr erfahren.'}else if(act==='reveal'){s.used='revealed';state.private.reputation+=s.category==='private'?-5:2;state.stats.intelligence+=2;if(s.country)state.relations[s.country]-=10;text='Die Krone veröffentlicht Belege und übernimmt Verantwortung für die Folgen der Enthüllung.'}else if(act==='pardon'){s.used='pardoned';state.stats.legitimacy+=2;state.life.empathy+=2;if(s.personId)livingAddMemory(s.personId,'Ein Geheimnis wurde vergeben',s.title,6,5);text='Das Wissen wird nicht als Waffe benutzt. Die betroffene Person erfährt von der bewussten Vergebung.'}else if(act==='destroy'){s.used='destroyed';ensurePrivateWorld().evidence-=4;state.private.secret+=2;text='Dokumente und Siegel verschwinden. Die Erinnerung beteiligter Menschen kann nicht verbrannt werden.'}else return false;s.lastHandledTurn=state.turn;crownDepthCommit(`Schwarze Chronik · ${s.title}`,text,'private');return true}

function crownPalacePanel(){let c=ensureCrownDepth(),id=c.palace.selected,room=CROWN_PALACE_ROOMS[id],s=c.palace.rooms[id],rooms=Object.entries(CROWN_PALACE_ROOMS).map(([rid,r])=>{let x=c.palace.rooms[rid];return `<button data-crown-palace="select:${rid}" class="palace-room ${rid===id?'active':''} ${x.level?'built':'locked'}" style="--room-level:${x.level}"><i>${r.icon}</i><b>${r.name}</b><span>${x.construction?'IM BAU · '+x.construction.left+' RUNDEN':x.level?'STUFE '+x.level:'NOCH NICHT ERRICHTET'}</span></button>`}).join(''),cost=Math.round(room.cost*(1+s.level*.65)),actions=s.level?room.acts.map(a=>`<button data-crown-palace="act:${id}:${a[0]}" ${s.usedTurn===state.turn?'disabled':''}><b>${a[1]}</b><span>Raumwirkung der Stufe ${s.level}</span></button>`).join(''):'';return panel('FALKENKRONE WÄCHST MIT DER DYNASTIE','Jeder Raum ist sichtbar, ausbaubar und eröffnet eigene wiederholbare Handlungen',`<div class="palace-hero"><img src="assets/crown-palace-depth.webp" alt="Der ausgebaute Palast Falkenkrone"><div><small>PALASTPRESTIGE ${c.palace.prestige}</small><h2>${room.name}</h2><p>${room.text}</p></div></div><div class="palace-layout"><div class="palace-room-map">${rooms}</div><div class="palace-room-detail"><span>${room.icon}</span><h3>${room.name}</h3><p>${room.text}</p><div>${actions}${s.level<3&&!s.construction?`<button data-crown-palace="build:${id}" ${state.buildingFund<cost?'disabled':''}><b>${s.level?'WEITER AUSBAUEN':'ERRICHTEN'} · ${fmt(cost)} ₲</b><span>${2+s.level} Runden Bauzeit · maximal drei Entwicklungsstufen</span></button>`:''}${s.construction?`<div class="palace-building-state"><b>IM BAU</b><span>Noch ${s.construction.left} Runden bis zur Eröffnung.</span></div>`:''}</div></div></div>`,'span-12')}
function crownPalaceAction(code){let [act,id,choice]=code.split(':'),c=ensureCrownDepth(),room=CROWN_PALACE_ROOMS[id],s=c.palace.rooms[id];if(act==='select'&&room){c.palace.selected=id;persist();render(false);return true}if(!room||!s)return false;if(act==='build'){if(s.construction||s.level>=3)return false;let cost=Math.round(room.cost*(1+s.level*.65));if(state.buildingFund<cost)return false;state.buildingFund-=cost;s.construction={left:2+s.level,target:s.level+1,cost};crownDepthCommit(`Palastbau · ${room.name}`,`Steinmetze, Künstler und der königliche Haushalt beginnen Stufe ${s.level+1}. Der Raum wird nach ${s.construction.left} Runden eröffnet.`,'development');return true}if(act==='act'){if(!s.level||s.usedTurn===state.turn)return false;s.usedTurn=state.turn;c.palace.prestige+=s.level;let text='';if(id==='throne'){state.stats.legitimacy+=2*s.level;state.life.authority+=1;text='Der Thronsaal macht Urteil und Rang vor Zeugen sichtbar.'}else if(id==='apartments'){state.private.stress-=4*s.level;state.private.queen+=2*s.level;text='Die privaten Gemächer schützen Zeit, Familie und persönliche Nähe.'}else if(id==='library'){state.stats.intelligence+=2*s.level;state.life.education+=1;text='Die Bibliothek übersetzt alte Texte in gegenwärtige Regierung.'}else if(id==='theatre'){state.private.reputation+=2*s.level;c.society.printers.satisfaction+=2;text='Das Theater lässt Kunst und Öffentlichkeit miteinander streiten.'}else if(id==='gardens'){state.private.health+=2*s.level;state.factions.nobles+=1;text='Die Gärten schaffen Nähe ohne die Enge eines Audienzsaals.'}else if(id==='nursery'){state.private.heir+=3*s.level;for(const ch of state.life.children)ch.education=(ch.education||0)+1;text='Der Kinderflügel gibt der nächsten Generation Zeit und Schutz.'}else if(id==='vault'){state.reserve+=120000*s.level;state.private.purse+=60000*s.level;text='Die tiefe Schatzkammer trennt Reserve, Erbe und laufende Ausgaben.'}else if(id==='observatory'){state.stats.navy+=s.level;c.expedition.draft.fleet=Math.min(3,c.expedition.draft.fleet+1);text='Neue Sternkarten verbessern Navigation und Reichweite der Flotte.'}else{ensurePrivateWorld().secretCircle+=2*s.level;ensurePrivateWorld().exposure+=1;text='Die Halle unter dem Palast nimmt Menschen und Wahrheiten auf, die oben keinen Platz haben.'}s.history.unshift({year:state.year,text});crownDepthCommit(`Palastleben · ${room.name}`,text,'private');return true}return false}

function crownSocietyPanel(){let c=ensureCrownDepth(),cards=Object.entries(CROWN_SOCIETY_GROUPS).map(([id,g])=>{let s=c.society[id],demand=s.satisfaction<38||s.radicalism>55;return `<article class="society-group ${demand?'demand':''}"><i>${g.icon}</i><div><small>MACHT ${s.power} · WOHLSTAND ${s.wealth}</small><h3>${g.name}</h3><p>${g.text}</p><div class="society-bars"><span>ZUFRIEDENHEIT<b style="width:${s.satisfaction}%"></b></span><span>RADIKALISIERUNG<b style="width:${s.radicalism}%"></b></span></div>${demand?`<div class="society-demand"><b>${s.satisfaction<25?'DRINGENDE FORDERUNG':'ÖFFENTLICHE PETITION'}</b><span>${g.faction==='nobles'?'Ämter, Rang und alte Rechte schützen.':g.faction==='officers'?'Versorgung und Land für geleisteten Dienst.':'Mehr Zugang, Schutz und Mitsprache im Reich.'}</span><button data-crown-society="accept:${id}">ANNEHMEN</button><button data-crown-society="negotiate:${id}">AUSHANDELN</button><button data-crown-society="refuse:${id}">ABLEHNEN</button></div>`:''}</div></article>`}).join('');return panel('EINE GESELLSCHAFT IN BEWEGUNG','Neue Gruppen entstehen aus Jahrzehnten von Krieg, Bildung, Handel und Gesetzen',`<div class="society-overview">${cards}</div>`,'span-12')}
function crownSocietyAction(code){let [act,id]=code.split(':'),c=ensureCrownDepth(),s=c.society[id],g=CROWN_SOCIETY_GROUPS[id];if(!s||s.lastResponse===state.turn)return false;let text='';if(act==='accept'){let cost=500000+Math.round(s.power*18000);if(state.reserve<cost)return false;state.reserve-=cost;s.satisfaction+=14;s.radicalism-=8;s.power+=2;state.factions[g.faction]+=3;text=`Die Krone erfüllt die zentrale Forderung von ${g.name} und finanziert ihre Umsetzung.`}else if(act==='negotiate'){s.satisfaction+=7;s.radicalism-=3;state.life.diplomacy+=2;state.factions[g.faction]+=1;text=`Vertreter von ${g.name} handeln mit dem Hof einen begrenzten, überprüfbaren Kompromiss aus.`}else if(act==='refuse'){s.satisfaction-=9;s.radicalism+=11;state.life.authority+=2;state.factions[g.faction]-=3;text=`Die Forderung von ${g.name} wird zurückgewiesen. Die Gruppe verliert nicht ihre Organisation.`}else return false;s.lastResponse=state.turn;s.history.unshift({year:state.year,act,text});crownDepthCommit(`Gesellschaft · ${g.name}`,text,'realm');return true}

function crownLawName(d){let a={all:'Allgemeines',cities:'Städtisches',land:'Ländliches',crown:'Königliches'}[d.subject],b={liberty:'Freiheitsrecht',duty:'Pflichtgesetz',protection:'Schutzgesetz',access:'Zugangsgesetz'}[d.right];return `${a} ${b}`}
function crownLawScore(d){let c=ensureCrownDepth(),score=42+state.stats.legitimacy*.18+state.life.diplomacy*.22;if(d.exception==='none')score-=c.society.oldnobles.power*.12;if(d.oversight==='communities')score+=c.society.communes.satisfaction*.1-state.factions.nobles*.08;if(d.funding==='treasury')score+=state.reserve>15000000?7:-12;if(d.enforcement==='mediation')score+=5;return clamp(Math.round(score),8,92)}
function crownLawPanel(){let c=ensureCrownDepth(),d=c.lawDraft,fields=Object.entries(CROWN_LAW_FIELDS).map(([fid,f])=>`<section><small>${f.label}</small>${Object.entries(f.options).map(([id,x])=>`<button data-crown-law="field:${fid}:${id}" class="${d[fid]===id?'active':''}">${x[0]}</button>`).join('')}</section>`).join(''),score=crownLawScore(d),laws=c.customLaws.slice(0,5).map(l=>`<article><time>${l.year}</time><b>${l.name}</b><span>${Object.values(l.fields).join(' · ')}</span><em>WIRKUNG ${l.support}%</em></article>`).join('')||'<div class="empty">Noch wurde kein eigenes zusammengesetztes Reichsgesetz geschaffen.</div>';return panel('DER KÖNIGLICHE GESETZESBAUKASTEN','Sechs Entscheidungen ergeben ein eigenes Gesetz mit dauerhaften gesellschaftlichen Folgen',`<div class="law-builder"><div class="law-fields">${fields}</div><aside><small>ENTWURF</small><h2>${crownLawName(d)}</h2><p>Geltungsbereich, Recht, Finanzierung, Kontrolle, Durchsetzung und Ausnahmen werden gemeinsam beschlossen.</p><div class="law-support"><i style="--support:${score}"><b>${score}%</b></i><span>ERWARTETE TRAGFÄHIGKEIT</span></div><button data-crown-law="enact" ${state.life.age<16||state.year-c.lastLawYear<2||state.reserve<750000?'disabled':''}>GESETZ BESIEGELN · 0,75 MIO. ₲</button></aside></div><div class="custom-law-history">${laws}</div>`,'span-12')}
function crownLawAction(code){let [act,field,val]=code.split(':'),c=ensureCrownDepth();if(act==='field'&&CROWN_LAW_FIELDS[field]?.options[val]){c.lawDraft[field]=val;persist();render(false);return true}if(act!=='enact'||state.life.age<16||state.year-c.lastLawYear<2||state.reserve<750000)return false;let d={...c.lawDraft},support=crownLawScore(d),name=crownLawName(d);state.reserve-=750000;c.lastLawYear=state.year;c.customLaws.unshift({id:'law_'+state.turn+'_'+c.customLaws.length,name,year:state.year,fields:d,support});c.customLaws=c.customLaws.slice(0,20);let targets=d.subject==='cities'?['artisans','bourgeois','printers']:d.subject==='land'?['communes','oldnobles']:Object.keys(c.society);for(const id of targets){let s=c.society[id];s.satisfaction+=support>=55?6:-2;s.radicalism+=support>=55?-3:2;if(d.right==='access'||d.right==='liberty')s.power+=2}if(d.funding==='levy')state.factions.people-=2;if(d.exception==='noble')state.factions.nobles+=4;else if(d.exception==='none')state.factions.nobles-=3;if(d.oversight==='courts')state.stats.legitimacy+=2;else if(d.oversight==='communities')state.factions.people+=3;c.traitScores.lawgiver+=5;crownDepthCommit(`Neues Reichsgesetz · ${name}`,`Das Gesetz gilt für ${CROWN_LAW_FIELDS.subject.options[d.subject][0].toLowerCase()}, schafft ${CROWN_LAW_FIELDS.right.options[d.right][0].toLowerCase()} und wird durch ${CROWN_LAW_FIELDS.oversight.options[d.oversight][0].toLowerCase()} kontrolliert.`,'realm');return true}

function crownExpeditionPanel(){let c=ensureCrownDepth(),e=c.expedition;if(e.active){let a=e.active,event=a.pendingEvent;return panel('DIE FLOTTE JENSEITS DER KARTEN',event?event.title:`${a.name} · ${a.progress}% der Fahrt`, `<div class="expedition-live"><img src="assets/crown-expedition-depth.webp" alt="Valdorische Flotte vor unbekannten Inseln"><div><small>${CROWN_EXPEDITIONS.purposes[a.purpose][0]} · ${CROWN_EXPEDITIONS.routes[a.route][0]}</small><h2>${event?event.title:a.name}</h2><p>${event?event.text:`Unter ${a.captainName} folgt die Expedition dem Auftrag „${CROWN_EXPEDITIONS.purposes[a.purpose][1]}“. Vorräte ${a.supplies}%, Moral ${a.morale}%.`}</p><div class="expedition-progress"><i style="width:${a.progress}%"></i></div>${event?`<div class="expedition-choices">${event.choices.map(x=>`<button data-crown-expedition="event:${x[0]}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</div>`:'<small>Die nächste Lage entsteht während kommender Runden.</small>'}</div></div>`,'span-12')}let d=e.draft,people=ensureLiving().people.filter(p=>p.alive&&p.age>=22&&['council','court','nobility'].includes(p.group)).slice(0,12),captains=people.map(p=>`<button data-crown-expedition="captain:${p.id}" class="${d.captain===p.id?'active':''}"><b>${p.name}</b><span>${p.role} · ${p.traits.join(', ')}</span></button>`).join(''),purposes=Object.entries(CROWN_EXPEDITIONS.purposes).map(([id,x])=>`<button data-crown-expedition="purpose:${id}" class="${d.purpose===id?'active':''}"><b>${x[0]}</b><span>${x[1]}</span></button>`).join(''),routes=Object.entries(CROWN_EXPEDITIONS.routes).map(([id,x])=>`<button data-crown-expedition="route:${id}" class="${d.route===id?'active':''}"><b>${x[0]}</b><span>${x[1]} Runden · Gefahr ${x[2]}</span></button>`).join(''),conduct=Object.entries(CROWN_EXPEDITIONS.conduct).map(([id,x])=>`<button data-crown-expedition="conduct:${id}" class="${d.conduct===id?'active':''}">${x[0]}</button>`).join(''),cost=1200000+d.fleet*1400000;return panel('EXPEDITIONEN JENSEITS DER BEKANNTEN SEE','Kapitän, Schiffe, Auftrag, Route und Verhalten bestimmen eine mehrjährige Fahrt',`<div class="expedition-hero"><img src="assets/crown-expedition-depth.webp" alt="Unbekannte grüne Archipele"><div><h2>WO DIE KARTE ENDET</h2><p>Eine Expedition kann Wissen, Handel, einen Stützpunkt, verlorene Menschen oder eine Katastrophe zurückbringen.</p></div></div><div class="expedition-planner"><section><small>KAPITÄN ODER KAPITÄNIN</small>${captains}</section><section><small>AUFTRAG</small>${purposes}</section><section><small>ROUTE</small>${routes}</section><section><small>VERHALTEN IN DER FERNE</small>${conduct}<div class="fleet-size"><button data-crown-expedition="fleet:down">−</button><b>${d.fleet} SCHIFFE</b><button data-crown-expedition="fleet:up">+</button></div><button class="expedition-start" data-crown-expedition="start" ${!d.captain||state.reserve<cost?'disabled':''}>EXPEDITION AUSRÜSTEN · ${fmt(cost)} ₲</button></section></div>`,'span-12')}
function crownExpeditionAction(code){let [act,val]=code.split(':'),c=ensureCrownDepth(),e=c.expedition,d=e.draft;if(act==='captain'&&crownDepthPerson(val)){d.captain=val;persist();render(false);return true}if(act==='purpose'&&CROWN_EXPEDITIONS.purposes[val]){d.purpose=val;persist();render(false);return true}if(act==='route'&&CROWN_EXPEDITIONS.routes[val]){d.route=val;persist();render(false);return true}if(act==='conduct'&&CROWN_EXPEDITIONS.conduct[val]){d.conduct=val;persist();render(false);return true}if(act==='fleet'){d.fleet=clamp(d.fleet+(val==='up'?1:-1),1,3);persist();render(false);return true}if(act==='start'){let p=crownDepthPerson(d.captain),cost=1200000+d.fleet*1400000;if(!p||e.active||state.reserve<cost)return false;state.reserve-=cost;let route=CROWN_EXPEDITIONS.routes[d.route];e.active={...d,name:`Fahrt der ${['Morgenstern','Silbermöwe','Grenzenlosen Krone'][crownDepthHash(state.turn+state.nameSeed)%3]}`,captainName:p.name,started:state.year,progress:0,supplies:100,morale:72+d.fleet*4,duration:route[1],danger:route[2],stage:0,pendingEvent:null,log:[]};livingAddMemory(p.id,'Jenseits der bekannten Karten',`Der König übertrug ${p.name} eine Expedition mit ${d.fleet} Schiffen.`,5,5);crownDepthCommit(`Expedition beginnt · ${e.active.name}`,`${p.name} läuft mit ${d.fleet} Schiffen auf der Route ${route[0]} aus. Auftrag: ${CROWN_EXPEDITIONS.purposes[d.purpose][0]}.`,'diplomacy');return true}if(act==='event'&&e.active?.pendingEvent){let ev=e.active.pendingEvent,ch=ev.choices.find(x=>x[0]===val);if(!ch)return false;e.active.supplies+=ch[3]||0;e.active.morale+=ch[4]||0;e.active.danger+=ch[5]||0;e.active.log.unshift({year:state.year,title:ev.title,choice:ch[1]});e.active.pendingEvent=null;crownDepthCommit(`Expedition · ${ev.title}`,`${ch[1]}. ${ch[2]} Diese Entscheidung reist mit den Überlebenden zurück.`,'diplomacy');return true}return false}
function crownExpeditionEvent(a){let events=[
 {title:'FIEBER UNTER DECK',text:'Mehrere Seeleute werden krank; die Ursache ist unklar, die Vorräte sind begrenzt.',choices:[['rest','IN EINER BUCHT ANKERN','Zeit verlieren, Kranken aber echte Erholung geben.',-5,5,-4],['ration','HEILMITTEL RATIONIEREN','Die Schwersten erhalten Vorrang, der Rest arbeitet weiter.',2,-5,4],['turn','EIN SCHIFF HEIMSCHICKEN','Kranke kehren zurück; die Expedition wird kleiner.',8,1,-6]]},
 {title:'DIE BEWOHNTE BUCHT',text:'Am Ufer warten Menschen mit Wasser, Werkzeugen und unbekannten Zeichen.',choices:[['trade','GESCHENKE UND ZEICHEN TAUSCHEN','Langsam entsteht ein erster verständlicher Austausch.',12,7,-5],['observe','AUF ABSTAND BLEIBEN','Die Küste wird kartiert, ohne Land zu beanspruchen.',2,1,-8],['claim','DAS KRONBANNER SETZEN','Der Anspruch ist sichtbar, aber nicht notwendig akzeptiert.',6,4,10]]},
 {title:'RUINEN ÜBER DEN WOLKEN',text:'Eine alte Treppe führt vom Strand zu Bauwerken, die keine Karte kennt.',choices:[['climb','EINE FORSCHUNGSGRUPPE HINAUFSCHICKEN','Inschriften und Kartenfragmente werden geborgen.',-8,5,7],['camp','EIN GESICHERTES LAGER BAUEN','Erkundung und Versorgung werden sorgfältig verbunden.',-4,4,-2],['leave','DEN ORT UNBERÜHRT LASSEN','Die Flotte wahrt Kräfte und vermerkt nur die Position.',4,-2,-5]]},
 {title:'DIE MAUER AUS STURM',text:'Eine schwarze Front schließt den Rückweg und zwingt zu einer Kursentscheidung.',choices:[['through','DURCH DEN STURM', 'Tempo und Mut werden über Schonung gestellt.',-15,-5,12],['shelter','ZWISCHEN DEN RIFFEN SCHUTZ SUCHEN','Gefährliche Navigation vermeidet die schwerste See.',-7,2,-3],['detour','WEIT NACH SÜDEN AUSWEICHEN','Vorräte kosten weniger als verlorene Schiffe.',-10,0,-7]]}
 ];return events[(a.stage+crownDepthHash(a.name))%events.length]}

function crownMemoryPanel(){let c=ensureCrownDepth(),traits=c.traits.map(id=>{let t=CROWN_MEMORY_TRAITS[id];return `<article><i>${t.icon}</i><b>${t.name}</b><span>${t.text}</span></article>`}).join('')||'<div class="empty">Noch hat keine wiederkehrende Haltung den Herrscher dauerhaft geprägt.</div>',mem=c.memories.slice(0,12).map(m=>`<article class="memory-${m.valence<0?'dark':'light'}"><time>${m.year}</time><div><b>${m.title}</b><span>${m.text}</span></div><em>PRÄGUNG ${m.importance}</em></article>`).join('')||'<div class="empty">Die prägenden Erinnerungen beginnen mit den Entscheidungen dieser Herrschaft.</div>';return panel('WAS DIE KRONE MIT DEM MENSCHEN MACHT','Erlebnisse verdichten sich zu Eigenschaften, die spätere Systeme wirklich verändern',`<div class="ruler-traits">${traits}</div><div class="ruler-memories">${mem}</div>`,'span-12')}
function crownDepthRememberDecision(title,text,meta={}){if(!state.crownDepth)return;let c=ensureCrownDepth(),words=(title+' '+text).toLowerCase(),val=/hilfe|schütz|gnade|freiheit|ehrlich|versöhn/.test(words)?3:/hinricht|demütig|vernicht|ablehn|zwingen/.test(words)?-3:1,importance=clamp(2+Math.abs(val)+(meta.kind==='war'?1:0),2,5);c.memories.unshift({turn:state.turn,year:state.year,title,text:text.slice(0,240),valence:val,importance,kind:meta.kind||'realm'});c.memories=c.memories.slice(0,80);for(const [id,t] of Object.entries(CROWN_MEMORY_TRAITS)){let hits=t.keys.filter(k=>words.includes(k)).length;if(hits)c.traitScores[id]+=hits*(1+importance*.35);if(c.traitScores[id]>=t.need&&!c.traits.includes(id)){c.traits.push(id);crownDepthNews(`Eine bleibende Eigenschaft · ${t.name}`,t.text,'trait')}}if(/brief|geheimnis|unehelich|bestech|verrat|fälsch|schmuggel|affäre|geliebt/.test(words)&&crownDepthHash(title+state.turn)%4===0){let id='secret_'+state.turn+'_'+c.secrets.length;if(!c.secrets.some(s=>s.title===title&&!s.used))c.secrets.unshift({id,year:state.year,title,origin:meta.target?`Über ${meta.target}`:'Aus einer königlichen Entscheidung',text:text.slice(0,260),category:meta.target?'foreign':meta.kind==='private'?'private':'court',country:meta.target||null,leverage:25+importance*8,exposure:5,used:null})}for(const [id,g] of Object.entries(CROWN_SOCIETY_GROUPS)){let s=c.society[id],joined=(id==='artisans'&&/bau|werk|straße|hafen/.test(words))||(id==='bourgeois'&&/bildung|amt|handel|gericht/.test(words))||(id==='printers'&&/druck|kunst|freiheit|chronik/.test(words))||(id==='veterans'&&/krieg|soldat|heer|flotte/.test(words))||(id==='oldnobles'&&/adel|stand|erbe|rang/.test(words))||(id==='reformers'&&/glaube|kirche|tempel|gewissen/.test(words))||(id==='communes'&&/bauern|dorf|gemeinde|land/.test(words));if(joined){s.momentum+=1;s.satisfaction+=val;s.radicalism+=val<0?2:-1}}if(meta.target&&c.rivals[meta.target]){let r=c.rivals[meta.target];r.respect+=meta.kind==='war'?1:val>0?2:0;r.resentment+=val<0?3:0}}
function crownLegacySnapshot(monarch=ensureCastNames().king){let c=ensureCrownDepth(),avgSoc=Object.values(c.society).reduce((n,x)=>n+x.satisfaction,0)/Object.keys(c.society).length,privateWorld=ensurePrivateWorld(),family=Math.round((state.private.queen+state.private.heir+state.life.motherTrust)/3),people=Math.round((state.factions.people+avgSoc)/2),nobles=Math.round((state.factions.nobles+state.stats.legitimacy)/2),enemies=Math.round(Object.values(c.rivals).reduce((n,r)=>n+r.respect-r.resentment*.5,0)/5),historians=Math.round((state.stats.intelligence+c.palace.prestige+c.customLaws.length*4+c.expedition.discoveries.length*5)/3);return {monarch,year:state.year,turn:state.turn,traits:[...c.traits],perspectives:{family:clamp(family,0,100),people:clamp(people,0,100),nobles:clamp(nobles,0,100),enemies:clamp(enemies,0,100),historians:clamp(historians,0,100)},summary:{laws:c.customLaws.length,discoveries:c.expedition.discoveries.length,festivals:c.festival.history.length,palace:c.palace.prestige,secrets:c.secrets.filter(s=>s.used==='revealed').length,scandals:privateWorld.scandalHistory.length},memories:c.memories.slice(0,8)}}
function crownLegacyPanel(){let c=ensureCrownDepth(),now=crownLegacySnapshot(),all=[now,...c.legacies].slice(0,8),cards=all.map((l,i)=>`<article class="legacy-voices ${i===0?'current':''}"><small>${i===0?'WÜRDE DIE HERRSCHAFT HEUTE ENDEN':`GESTORBEN ${l.year}`}</small><h3>${l.monarch}</h3><div>${Object.entries(l.perspectives).map(([k,v])=>`<span><b>${{family:'FAMILIE',people:'VOLK',nobles:'ADEL',enemies:'FEINDE',historians:'CHRONISTEN'}[k]}</b><i><em style="width:${v}%"></em></i><strong>${v}</strong></span>`).join('')}</div><p>${l.summary.laws} eigene Gesetze · ${l.summary.discoveries} Entdeckungen · ${l.summary.festivals} große Feste · Palast ${l.summary.palace}</p></article>`).join('');return panel('FÜNF STIMMEN ÜBER JEDE HERRSCHAFT','Familie, Volk, Adel, Feinde und Chronisten erinnern niemals denselben König',`<div class="legacy-voice-grid">${cards}</div>`,'span-12')}
function crownDepthSuccessionReset(snapshot){let c=ensureCrownDepth();if(snapshot)c.legacies.unshift(snapshot);c.legacies=c.legacies.slice(0,20);for(const r of Object.values(c.rivals)){r.bond=Math.round(r.bond*.45);r.resentment=Math.round(r.resentment*.75);r.respect=Math.round(r.respect*.65);r.lastTurn=0}for(const slot of Object.values(c.household.roles)){slot.trust=Math.round(slot.trust*.6);slot.usedTurn=0}c.memories=[];c.traitScores=Object.fromEntries(Object.keys(CROWN_MEMORY_TRAITS).map(k=>[k,0]));c.traits=[];c.festival.active=null;c.expedition.draft.captain=null;crownDepthNews('Ein neuer Mensch in einem alten Palast','Haushalt, Gesellschaft, fremde Kronen und gebaute Räume bestehen fort; Charakter und persönliche Erinnerungen beginnen neu.','generation')}

function crownDepthTurn(){let c=ensureCrownDepth();for(const [id,s] of Object.entries(c.palace.rooms))if(s.construction&&--s.construction.left<=0){s.level=s.construction.target;s.history.unshift({year:state.year,text:`${CROWN_PALACE_ROOMS[id].name} wurde auf Stufe ${s.level} eröffnet.`});s.construction=null;c.palace.prestige+=4+s.level*2;crownDepthNews(`${CROWN_PALACE_ROOMS[id].name} eröffnet`,`Der neue Palastbereich ist sichtbar und seine Handlungen stehen ab sofort zur Verfügung.`,'palace')}for(const [id,s] of Object.entries(c.society)){s.power+=s.momentum*.08;s.momentum*=.88;s.satisfaction+=(s.wealth-50)*.015;s.radicalism+=(45-s.satisfaction)*.025-(state.stats.stability-50)*.012;if(s.radicalism>72)state.stats.stability-=.25*s.power/50;if(s.satisfaction>68)state.stats.legitimacy+=.08}for(const slot of Object.values(c.household.roles)){let p=crownDepthPerson(slot.personId);if(!p)continue;slot.trust+=(p.relation-50)*.012;if(p.health<25)slot.trust-=.2}for(const [n,r] of Object.entries(c.rivals)){let war=state.diplo[n]?.war,policy=state.countryPolicy?.[n];if(policy?.occupied&&!r.captureTurn){r.captureTurn=state.turn;r.status='captured';r.defeatResolved=false;r.resentment+=20;r.respect+=7;r.encounters.unshift({year:state.year,title:`Der Fall von ${n}`,text:`${livingForeignRealm(n).ruler} gerät nach dem Zusammenbruch der Hauptstadt in valdorische Gewalt. Über die Person hinter der besiegten Krone muss entschieden werden.`});crownDepthNews(`Die Krone von ${n} ist gefangen`,`Die Landkarte zeigt den militärischen Sieg; im Palast wartet nun ein Mensch auf Freilassung, Hausarrest oder Lösegeld.`,'diplomacy')}if(war){r.resentment+=.7;r.respect+=state.stats.army>60?.15:0}else{r.resentment-=.12;if((state.relations[n]||0)>45)r.bond+=.12}r.respect=clamp(r.respect,0,100);r.resentment=clamp(r.resentment,0,100);r.bond=clamp(r.bond,0,100)}let a=c.expedition.active;if(a&&!a.pendingEvent){a.stage++;a.progress=clamp(Math.round(a.stage/a.duration*100),0,100);a.supplies-=4+Math.max(0,2-a.fleet);a.morale-=a.supplies<35?3:0;if(a.stage<a.duration&&a.stage%2===0)a.pendingEvent=crownExpeditionEvent(a);if(a.stage>=a.duration){let chance=clamp(72+a.fleet*7-a.danger*.45+a.morale*.18+(c.palace.rooms.observatory.level*6),18,94),success=crownDepthHash(`${state.nameSeed}:${a.name}:return`)%100<chance,discovery={year:state.year,name:success?['Die Inseln von Aster','Die Ruinen von Varos','Die Morgenpassage','Das Grüne Kap'][crownDepthHash(a.name)%4]:'Die unvollendete Route',purpose:a.purpose,success};if(success){state.reserve+=a.purpose==='trade'?4200000:a.purpose==='settlement'?2500000:1600000;state.stats.navy+=3;state.stats.intelligence+=a.purpose==='science'?6:2;if(a.purpose==='settlement'){let id='exp_'+state.turn+'_'+c.expedition.discoveries.length;state.colonies.push({id,name:discovery.name,founded:state.turn,loyalty:55,yield:500000})}}else{state.stats.navy-=3;state.private.stress+=4}c.expedition.discoveries.unshift(discovery);c.expedition.history.unshift({...a,ended:state.year,success});let captain=crownDepthPerson(a.captain);if(captain)livingAddMemory(captain.id,success?'Von jenseits der Karten zurückgekehrt':'Die Fahrt, die Valdoria zeichnete',a.name,success?7:-5,5);crownDepthNews(success?`${a.name} kehrt zurück`:`Verluste auf ${a.name}`,success?`${a.captainName} bringt Karten, Menschen und die Nachricht von ${discovery.name}.`:`Die Flotte kehrt beschädigt und ohne vollständigen Auftrag zurück.`, 'expedition');c.expedition.active=null;c.traitScores.explorer+=success?5:2}}crownDepthNormalize(state)}
function crownDepthNormalize(s){let c=s.crownDepth;if(!c)return;for(const x of Object.values(c.society))for(const k of ['power','satisfaction','radicalism','wealth'])x[k]=clamp(Math.round(x[k]),0,100);for(const r of Object.values(c.rivals))for(const k of ['respect','resentment','bond'])r[k]=clamp(Math.round(r[k]),0,100);for(const slot of Object.values(c.household.roles))slot.trust=clamp(Math.round(slot.trust),0,100);for(const k in c.traitScores)c.traitScores[k]=Math.max(0,Math.round(c.traitScores[k]*10)/10);c.palace.prestige=Math.max(0,Math.round(c.palace.prestige))}
function crownDepthBindUI(){document.querySelectorAll('[data-crown-household]').forEach(b=>b.onclick=()=>crownHouseholdAction(b.dataset.crownHousehold));document.querySelectorAll('[data-crown-festival]').forEach(b=>b.onclick=()=>crownFestivalAction(b.dataset.crownFestival));document.querySelectorAll('[data-crown-rival]').forEach(b=>b.onclick=()=>crownRivalAction(b.dataset.crownRival));document.querySelectorAll('[data-crown-secret]').forEach(b=>b.onclick=()=>crownSecretAction(b.dataset.crownSecret));document.querySelectorAll('[data-crown-palace]').forEach(b=>b.onclick=()=>crownPalaceAction(b.dataset.crownPalace));document.querySelectorAll('[data-crown-society]').forEach(b=>b.onclick=()=>crownSocietyAction(b.dataset.crownSociety));document.querySelectorAll('[data-crown-law]').forEach(b=>b.onclick=()=>crownLawAction(b.dataset.crownLaw));document.querySelectorAll('[data-crown-expedition]').forEach(b=>b.onclick=()=>crownExpeditionAction(b.dataset.crownExpedition))}
